-- Create "calendar_connections" table
CREATE TABLE "calendar_connections" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "subject" character varying NOT NULL, "email" character varying NOT NULL, "sealed_token" bytea NOT NULL, "status" character varying NOT NULL DEFAULT 'connected', "created_at" timestamptz NOT NULL, "user_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "calendar_connections_users_calendar_connection" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "calendar_connections_user_id_key" to table: "calendar_connections"
CREATE UNIQUE INDEX "calendar_connections_user_id_key" ON "calendar_connections" ("user_id");
-- Create "calendar_links" table
CREATE TABLE "calendar_links" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "link_hash" bytea NOT NULL, "state_hash" bytea NULL, "code_verifier" character varying NULL, "nonce" character varying NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, "user_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "calendar_links_users_calendar_links" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "calendar_links_link_hash_key" to table: "calendar_links"
CREATE UNIQUE INDEX "calendar_links_link_hash_key" ON "calendar_links" ("link_hash");
-- Create index "calendar_links_state_hash_key" to table: "calendar_links"
CREATE UNIQUE INDEX "calendar_links_state_hash_key" ON "calendar_links" ("state_hash");
